ssize_t macvtap_get_user_data(struct macvtap_queue *q, struct msghdr *m,
                              const struct iovec *iv, unsigned long total_len,
                              size_t count, int noblock) {
    struct sockbuf skb;
    int zcopy = 0;
    ssize_t ret = 0;

    if (!q || !m || !iv || total_len == 0 || count == 0) {
        return -EINVAL;
    }

    if (total_len > MACVTAP_MAX_DATA_SIZE) {
        return -EMSGSIZE;
    }

    if (noblock && !macvtap_can_nonblock(q)) {
        return -EWOULDBLOCK;
    }

    if (macvtap_supports_zcopy(q)) {
        zcopy = 1;
        skb = allocate_skb_zcopy(iv, total_len, count);
    } else {
        skb = allocate_skb_copy(iv, total_len, count);
    }

    if (!skb) {
        return -ENOMEM;
    }

    if (needs_virtual_header(m)) {
        setup_virtual_header(skb, m);
    }

    ret = process_skb(skb, m, q->vlan_dev);
    if (ret < 0) {
        free_skb(skb, zcopy);
        return ret;
    }

    return total_len;
}

ssize_t macvtap_skb_recvmsg(struct macvtap_queue *q, struct msghdr *m,
                             const struct iovec *iv, unsigned long total_len,
                             size_t count, int noblock)
{
    struct sk_buff *skb = NULL;
    ssize_t ret = -EINVAL;
    bool zcopy = false;
    struct vlan_dev_info *vlan_info = NULL;
    struct net_device *vlan_dev = NULL;

    if (!q || !m || !iv || count == 0 || total_len == 0)
        return ret;

    /* Determine if zero-copy is applicable */
    if (m->msg_flags & MSG_ZEROCOPY) {
        zcopy = true;
    }

    skb = alloc_skb(total_len, GFP_KERNEL);
    if (!skb)
        return -ENOMEM;

    if (zcopy) {
        /* Map user space data directly */
        if (skb_copy_datagram_from_iter(skb, 0, &m->msg_iter, total_len, 0)) {
            ret = -EFAULT;
            goto out;
        }
    } else {
        /* Copy data into skb */
        ret = skb_copy_datagram_from_iovec(skb, 0, iv, 0, total_len);
        if (ret < 0)
            goto out;
    }

    /* Set network headers if needed */
    skb_set_network_header(skb, 0);

    /* Determine VLAN device */
    vlan_info = q->vlan_info;
    if (!vlan_info) {
        ret = -ENODEV;
        goto out;
    }

    vlan_dev = vlan_info->real_dev;
    if (!vlan_dev) {
        ret = -ENODEV;
        goto out;
    }

    /* Transmit the skb through VLAN device */
    ret = dev_queue_xmit(skb);
    if (ret < 0) {
        goto out;
    }

    ret = total_len;
    if (zcopy)
        m->msg_flags |= MSG_ZERO_COPY;

out:
    if (ret < 0) {
        if (skb)
            kfree_skb(skb);
    }

    return ret;
}

ssize_t handle_macvtap_user_data(struct macvtap_queue *q, struct msghdr *m,
                                 const struct iovec *iv, unsigned long total_len,
                                 size_t count, int noblock) {
    struct sk_buff *skb = NULL;
    struct vlan_dev_info *vlan_info;
    ssize_t ret = -EFAULT;
    size_t copied = 0;
    int zcopy = 0;

    if (!q || !m || !iv || total_len == 0 || count == 0) {
        return -EINVAL;
    }

    /* Determine zero-copy applicability */
    if (m->msg_flags & MSG_ZEROCOPY) {
        zcopy = 1;
    }

    /* Allocate socket buffer */
    skb = alloc_skb(0, GFP_KERNEL);
    if (!skb) {
        return -ENOMEM;
    }

    skb_set_owner_w(skb, current->files);

    /* Map user space data based on zero-copy flag */
    if (zcopy) {
        if (import_iovec(m, iv, count, 1, &iov, &total_len)) {
            kfree_skb(skb);
            return -EFAULT;
        }
        skb_zerocopy_user(skb, iov, count);
    } else {
        if (copy_from_user(skb->data, iov, total_len)) {
            kfree_skb(skb);
            return -EFAULT;
        }
    }

    /* Set network headers */
    if (has_vlan_header(q)) {
        vlan_info = VLAN_DEV_INFO(q->dev);
        skb->data -= VLAN_HLEN;
        skb->len += VLAN_HLEN;
        skb_set_network_header(skb, VLAN_HLEN);
    }

    /* Transmit the skb through the VLAN device */
    ret = dev_queue_xmit(skb);
    if (ret < 0) {
        kfree_skb(skb);
    }

    return ret;
}

ssize_t macvtap_get_user(struct macvtap_queue *q, struct msghdr *m,
                         const struct iovec *iv, unsigned long total_len,
                         size_t count, int noblock)
{
    struct sk_buff *skb;
    int zero_copy = 0;
    ssize_t ret = -EFAULT;

    if (!q || !m || !iv || total_len == 0 || count == 0)
        return -EINVAL;

    if (total_len > MACVTAP_QUEUE_MAX_SIZE)
        return -EMSGSIZE;

    if (noblock) {
        if (skb_queue_len(&q->tx_queue) > 0)
            return -EBUSY;
    }

    skb = alloc_skb(ETH_HLEN + LL_ALLOCATED_SPACE, GFP_KERNEL);
    if (!skb)
        return -ENOMEM;

    if (zero_copy && can_zero_copy(iv, count)) {
        ret = skb_zerocopy_from_iovec(skb, iv, count);
        if (ret < 0)
            goto error;
    } else {
        ret = skb_copy_from_linear_data(skb, iv, count);
        if (ret < 0)
            goto error;
    }

    skb_set_network_header(skb, ETH_HLEN);
    skb->protocol = eth_type_trans(skb, q->vlan_dev);
    skb->dev = q->vlan_dev;

    if (skb_vlan_tag_present(skb)) {
        skb->vlan_tci = q->vlan_id;
    }

    ret = dev_queue_xmit(skb);
    if (ret < 0)
        goto error;

    return total_len;

error:
    kfree_skb(skb);
    return ret;
}

ssize_t handle_macvtap_queue(struct macvtap_queue *q, struct msghdr *m,
                             const struct iovec *iv, unsigned long total_len,
                             size_t count, int noblock) {
    struct sk_buff *skb = NULL;
    size_t len = 0;
    int err = 0;
    ssize_t ret = -EFAULT;
    unsigned int zerocopy = 0;

    if (!q || !m || !iv || !total_len || !count)
        return -EINVAL;

    if (m->msg_flags & MSG_ZEROCOPY)
        zerocopy = 1;

    skb = alloc_skb(0, GFP_KERNEL);
    if (!skb)
        return -ENOMEM;

    if (zerocopy) {
        err = skb_zerocopy(skb, iv, count, total_len);
        if (err < 0)
            goto out;
    } else {
        err = skb_copy_datagram_from_iter(skb, 0, &m->msg_iter, total_len, 0);
        if (err < 0)
            goto out;
    }

    skb_set_network_header(skb, 0);

    if (q->vlan_dev) {
        err = vlan_dev_set_header(q->vlan_dev, skb);
        if (err < 0)
            goto out;
    }

    if (q->tx_fn && q->tx_fn(skb, q) < 0) {
        err = -EIO;
        goto out;
    }

    ret = (ssize_t)total_len;

out:
    if (err < 0)
        kfree_skb(skb);

    if (zerocopy && m->msg_flags & MSG_WAITFORONE)
        m->msg_flags &= ~MSG_ZEROCOPY;

    return ret;
}
